List<int> strangeSortList(List<int> lst) {
  List<int> res = [];
  List<int> remaining = List.from(lst);
  bool useMin = true;

  while (remaining.isNotEmpty) {
    int value;
    if (useMin) {
      value = remaining.reduce((a, b) => a < b ? a : b);
    } else {
      value = remaining.reduce((a, b) => a > b ? a : b);
