bool willItFly(List<int> q, int w) {
  int sum = 0;
  for (int num in q) {
    sum += num;
  }

  if (sum > w) {
    return false;
  }

  int i = 0;
  int j = q.length - 1;
  while (i < j) {
    if (q[i] != q[j]) {
      return false;
    }
    i++;
    j--;
  }
  return true;
}

