int digitsSum(int n) {
  int neg = 1;
  if (n < 0) {
    n = -1 * n;
    neg = -1;
  }
  List<int> digits = n.toString().split('').map((i) => int.parse(i)).toList();
  digits[0] = digits[0] * neg;
  return digits.reduce((a, b) => a + b);
}

