List<int> orderByPoints(List<int> nums) {
  List<MapEntry<int, int>> indexed = [];
  for (int i = 0; i < nums.length; i++) {
    indexed.add(MapEntry(i, nums[i]));
  }

  indexed.sort((a, b) {
    int sumA = digitsSum(a.value);
    int sumB = digitsSum(b.value);
    if (sumA != sumB) {
      return sumA.compareTo(sumB);
    }
    return a.key.compareTo(b.key);
  });

